WebScreens.wsOnDataLoad:
this.fields.lmlActive = 0;

this.fields.lmlRoundedStartTime =  m1.currentTime();
this.fields.lmlRoundedEndTime =  m1.currentTime();
this.fields.lmlActualStartTime = m1.currentTime();
this.fields.lmlActualEndTime = m1.currentTime();

this.fields.lmlCreatedDate = m1.currentTime();

if (this.fields.impTrackLotNumbers == '1')
{
	this.lotNumber.show();
	this.selectLotNumber.show();
}
else
{
	this.lotNumber.hide();
	this.selectLotNumber.hide();
}

if (this.fields.impTrackSerialNumbers == '1')
{
	this.serialNumber.show();
	this.selectSerialNumber.show();
}
else
{
	this.serialNumber.hide();
	this.selectSerialNumber.hide();
}

if(this.fields.qanQualityRegisterID == null || this.fields.qanQualityRegisterID == '')
{
	this.fields.qanOpenedByEmployeeID = m1.employee;
	this.fields.qanOpenedDate = m1.currentTime();

	this.fields.qanSource = 3;			// Shop Floor Entry
	this.fields.qanQualityRegisterType = 3;		// Job
	this.createInspection.show();
}
else
{
	this.createInspection.hide();
}

if(m1.employee != this.fields.lmeEmployeeID)
{
	m1.job = null;
	m1.jobAssembly = null;
	m1.jobOperation= null;

	m1.setStoredValue('job', m1.job);
	m1.setStoredValue('jobAssembly', m1.jobAssembly);
	m1.setStoredValue('jobOperation', m1.jobOperation);
}

m1.employee = this.fields.lmeEmployeeID;
m1.setStoredValue('employee', m1.employee);

m1.employeeName = this.fields.lmeEmployeeName;
m1.setStoredValue('employeeName', m1.employeeName);

if(this.fields.lmpRoundedStartTime == null)
{
	this.clockOut.hide();
	this.clockIn.show();
	this.status.setValue("Out");
}
else
{
	this.clockOut.show();
	this.clockIn.hide();
	this.status.setValue("In");
}

this.completionType.setValue("2");
this.goodQuantity.setValue(this.fields.jmoOperationQuantity - this.fields.jmoQuantityComplete);

this.scrapQuantity.setValue(0);
this.scrapReason.hide();

this.reworkQuantity.setValue(0);
this.reworkReason.hide();

this.employeeName.setValue(m1.employeeName);

if ( this.fields.lmlTimecardID == null )
{
	this.status.setValue("Inactive");
	this.startIndirect.show();
	this.endIndirect.hide();
}
else
{
	this.status.setValue("Active");
	this.startIndirect.hide();
	this.endIndirect.show();
}

this.employeeName.setValue(m1.employeeName);

if(m1.mode == "count" && m1.countMode.count == this.fields.imnInventoryCountID) {
	this.countLines.show();
	this.startCounting.hide();
	this.stopCounting.show();
}
else {
	this.countLines.hide();
	this.startCounting.show();
	this.stopCounting.hide();
}

if(m1.mode == "job" && m1.jobMode.job == this.fields.jmpJobID && m1.jobMode.assembly == null){
	this.jobMaterials.show();
	this.startIssue.hide();
	this.stopIssue.show();
}
else{
	this.jobMaterials.hide();
	this.startIssue.show();
	this.stopIssue.hide();
}

if(m1.mode == "job" && m1.jobMode.job == this.fields.jmaJobID && m1.jobMode.assembly == this.fields.jmaJobAssemblyID){
	this.assemblyMaterials.show();
	this.startIssue.hide();
	this.stopIssue.show();
}
else{
	this.assemblyMaterials.hide();
	this.startIssue.show();
	this.stopIssue.hide();
}

quantityToIssue = this.fields.jmmEstimatedQuantity - this.fields.jmmQuantityReceived;

if(quantityToIssue < 0)
	quantityToIssue = 0;

this.quantityToIssue.setValue(quantityToIssue);

if (this.fields.impTrackLotNumbers == '1')
{
	this.lotNumber.show();
	this.selectLotNumber.show();
}
else
{
	this.lotNumber.hide();
	this.selectLotNumber.hide();
}

if (this.fields.impTrackSerialNumbers == '1')
{
	this.serialNumber.show();
	this.selectSerialNumber.show();
}
else
{
	this.serialNumber.hide();
	this.selectSerialNumber.hide();
}

this.quantityToIssue.setValue(this.fields.jmmEstimatedQuantity - this.fields.jmmQuantityReceived);

if (this.fields.impTrackLotNumbers == '1')
{
	this.lotNumber.show();
	this.selectLotNumber.show();
}
else
{
	this.lotNumber.hide();
	this.selectLotNumber.hide()
}

if (this.fields.impTrackSerialNumbers == '1')
{
	this.serialNumber.show();
	this.selectSerialNumber.show();
}
else
{
	this.serialNumber.hide();
	this.selectSerialNumber.hide();
}

if ( this.fields.lmlRoundedStartTime == null )
{
	this.endJob.hide();
	this.startProduction.show();
	this.startSetup.show();
	this.addScrap.hide();
	this.createInspection.hide();
}
else
{
	this.endJob.show();
	this.startProduction.hide();
	this.startSetup.hide();
	this.addScrap.show();
	this.createInspection.show();
}

if (this.fields.lmlWorkType == "1")
{
	this.status.setValue("Setup");
}
else if (this.fields.lmlWorkType == "2")
{
	this.status.setValue("Production");
}
else
{
	this.status.setValue("Inactive");
}

m1.job = this.fields.jmoJobID;
m1.jobAssembly = this.fields.jmoJobAssemblyID;
m1.jobOperation = this.fields.jmoJobOperationID;

m1.setStoredValue('job', m1.job);
m1.setStoredValue('jobAssembly', m1.jobAssembly);
m1.setStoredValue('jobOperation', m1.jobOperation);

this.employeeName.setValue(m1.employeeName);

this.quantityToIssue.setValue(this.fields.jmmEstimatedQuantity - this.fields.jmmQuantityReceived);

if(this.fields.jobMaterialCount == 1)
{
	this.warehouse.show();
	this.bin.show();
	this.quantityToIssue.show();	
	this.issueMaterial.show();

	if(this.fields.impTrackLotNumbers != 0)
	{
		this.lotNumber.show();
		this.selectLotNumber.show();
	}
	else
	{
		this.lotNumber.hide();
		this.selectLotNumber.hide();
	}

	if(this.fields.impTrackSerialNumbers != 0)
	{
		this.serialNumber.show();
		this.selectSerialNumber.show();
	}
	else
	{
		this.serialNumber.hide();
		this.selectSerialNumber.hide();
	}
}
else
{
	this.quantityToIssue.hide();
	this.issueMaterial.hide();
	this.lotNumber.hide();
	this.serialNumber.hide();
	this.selectLotNumber.hide();
	this.selectSerialNumber.hide();
	this.warehouse.hide();
	this.bin.hide();
}

if( m1.mode == "pickList" && m1.pickListMode.pickList == this.fields.omsPickListSessionID) {
	this.openPickListLines.show();
	this.startPicking.hide();
	this.stopPicking.show();
}
else {
	this.openPickListLines.hide();
	this.startPicking.show();
	this.stopPicking.hide();
}
